OTHER = [c for c in ALL if c not in OPS]

tot = {}
for f in sorted(glob.glob(os.path.join(W, 'out', 'seq-*.json'))):
    d = json.load(open(f)); k = (d['profile'], d['family'], d['spec'])
    t = tot.setdefault(k, {'cases': 0, 'mismatch': 0, 'errors': 0, 'pyevm_mismatch': 0, 'checks': 0, 'reverts': 0, 'commits': 0, 'steps': 0, 'seeds': []})
    t['seeds'].append(d['seed'])
    for x in ('cases', 'mismatch', 'errors', 'pyevm_mismatch', 'checks', 'reverts', 'commits', 'steps'): t[x] += d[x]
