faults = {}
for f in sorted(glob.glob(os.path.join(W, 'out', 'fault-*.json'))):
    d = json.load(open(f)); n = os.path.basename(f)[6:-5]
    faults[n] = (d['mismatch'] + d['errors'] > 0, d['fault_hits'], d['records'][0]['case'] if d['records'] else None)
fault_ok = all(v[0] and v[1] > 0 for v in faults.values())
ar = {'cases': 0, 'mismatches': 0, 'errors': 0, 'steps': 0}
for f in sorted(glob.glob(os.path.join(W, 'out', 'wc-arith-[0-9].json'))):
    d = json.load(open(f))
    for x in ar: ar[x] += d[x]
arf = {}
for f in sorted(glob.glob(os.path.join(W, 'out', 'wc-arith-fault-*.json'))):
    d = json.load(open(f)); arf[os.path.basename(f)[15:-5]] = d['mismatches'] + d['errors']
jd = json.load(open(os.path.join(W, 'out', 'wc-jd.json')))
jdf = json.load(open(os.path.join(W, 'out', 'wc-jd-fault-jumpdest_byte.json')))
cv = {x['chainId']: x.get('clientVersion') for x in json.load(open(os.path.join(W, 'out', 'clientversion.json')))}
cmp81 = json.load(open(os.path.join(W, 'out', 'cmp-opreth-2.10rc4-vs-2.8.1.json')))
cmpwc = json.load(open(os.path.join(W, 'out', 'cmp-opreth-2.10rc4-vs-worldchain-2.8.2.json')))

def src(u, s): return {'url': u, 'supports': s}

CODE = [src('src/PoolManager.sol:103-113', 'unlock sets the transient lock, runs the callback and requires NonzeroDeltaCount.read() == 0 before relocking; a frame revert inside the callback must restore these transient words'),
        src('src/libraries/Lock.sol:8', 'IS_UNLOCKED_SLOT 0xc090fc46...ab23, the lock key used in the sequences'),
        src('src/libraries/NonzeroDeltaCount.sol:9-32', 'NONZERO_DELTA_COUNT_SLOT read and written by tload and tstore'),
        src('src/libraries/CurrencyDelta.sol:21-39', 'deltas live at keccak(target, currency) in transient storage, written by tstore'),
        src('src/libraries/CurrencyReserves.sol:11-29', 'RESERVES_OF_SLOT and CURRENCY_SLOT in transient storage'),
        src('src/libraries/Hooks.sol:131-137', 'a hook call that fails reverts the whole PoolManager call with HookCallFailed; inner frames of hooks and tokens revert through the client journal')]

cleared = []
def C(chains, lens, check, result, source): cleared.append({'chainIds': chains, 'lens': lens, 'check': check, 'result': result, 'source': source})

